nodes.Process Tenure Data:
const payload = JSON.parse($input.first().json.data);

const areas = payload.dimensions[0].options;      // ltla list
const cats  = payload.dimensions[1].options;      // hh_tenure_9a list
const obs   = payload.observations;
const nCats = cats.length;                         // 9

// Build category index lookup by id
const catIdx = {};
cats.forEach((c, i) => catIdx[c.id] = i);

const rows = [];

for (let aIdx = 0; aIdx < areas.length; aIdx++) {
  const area = areas[aIdx];
  const code = area.id;

  // Only English LAs
  if (!code.startsWith('E')) continue;

  const base = aIdx * nCats;
  const get = (id) => obs[base + catIdx[id]] || 0;

  const owned_outright          = get('0');
  const owned_mortgage          = get('1');
  const shared_ownership        = get('2');
  const social_rented_council   = get('3');
  const social_rented_other     = get('4');
  const private_rented_landlord = get('5');
  const private_rented_other    = get('6');
  const lives_rent_free         = get('7');

  const total_households = owned_outright + owned_mortgage + shared_ownership +
                           social_rented_council + social_rented_other +
                           private_rented_landlord + private_rented_other +
                           lives_rent_free;

  rows.push({
    geography_code:           code,
    geography_name:           area.label,
    total_households,
    owned_outright,
    owned_mortgage,
    shared_ownership,
    social_rented_council,
    social_rented_other,
    private_rented_landlord,
    private_rented_other,
    lives_rent_free,
  });
}

return [{
  json: {
    row_count:  rows.length,
    batch_json: JSON.stringify(rows)
  }
}];

