const raw = $input.first().json.data;
const lines = raw.trim().split('\n');
const headers = lines[0].split(',');

function parseLine(line) {
  const cols = [];
  let cur = '', inQ = false;
  for (const ch of line) {
    if (ch === '"') { inQ = !inQ; }
    else if (ch === ',' && !inQ) { cols.push(cur); cur = ''; }
    else { cur += ch; }
  }
  cols.push(cur);
  return cols;
}

const rows = [];
for (let i = 1; i < lines.length; i++) {
  if (!lines[i].trim()) continue;
  const cols = parseLine(lines[i]);
  const obj = {};
  headers.forEach((h, idx) => obj[h.trim()] = (cols[idx] || '').trim());

  rows.push({
    lad24cd:                          obj.lad24cd,
    la_name:                          obj.la_name,
    imd_average_rank:                 parseFloat(obj.imd_average_rank),
    imd_rank_of_average_rank:         parseInt(obj.imd_rank_of_average_rank),
    imd_average_score:                parseFloat(obj.imd_average_score),
