// ── Parse EFS HTML — extract first table rows ───────────────────────────────
function parseEfsHtml(html, financial_year) {
  const rows = [];
  const trPattern = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;

  let trMatch;
  while ((trMatch = trPattern.exec(html)) !== null) {
    const cellContent = trMatch[1];
    const cells = [];
    const tdRe = /<td[^>]*>([\s\S]*?)<\/td>/gi;
    let tdMatch;
    while ((tdMatch = tdRe.exec(cellContent)) !== null) {
      const text = tdMatch[1]
        .replace(/<[^>]+>/g, ' ')
        .replace(/&amp;/g, '&')
        .replace(/&nbsp;/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
      cells.push(text);
    }
    if (cells.length !== 2) continue;

    const laName = cells[0].trim();
    const amountRaw = cells[1].trim();

    if (!laName || laName.toLowerCase().includes('local authority')) continue;
    if (/^\d{4}-\d{2}$/.test(laName)) continue;

    if (amountRaw.toLowerCase().includes('withdrew')) {
      rows.push({
        la_name: laName,
        financial_year,
        amount_m: null,
        status: 'withdrawn',
        hra_only: false,
      });
      continue;
    }

    const amountMatch = amountRaw.match(/£([\d,]+\.?\d*)\s*m/i);
    const amount_m = amountMatch
      ? parseFloat(amountMatch[1].replace(/,/g, ''))
      : null;

    rows.push({
      la_name: laName,
      financial_year,
      amount_m,
      status: 'agreed-in-principle',
      hra_only: false,
    });
  }
  return rows;
}

// ── Parse S114 CSV ──────────────────────────────────────────────────────────
function parseS114Csv(text) {
  const lines = text.trim().split('\n');
  const headers = lines[0].split(',');
  return lines.slice(1).map(line => {
    const cols = line.split(',');
    const obj = {};
    headers.forEach((h, i) => obj[h.trim()] = (cols[i] || '').trim());
    return obj;
  });
}

// ── Process EFS pages ───────────────────────────────────────────────────────
const efsRows = [];
const unresolved = [];

for (let i = 0; i < 7; i++) {
  const html = inputs[i].json.data;
  const year = EFS_YEARS[i];
  const parsed = parseEfsHtml(html, year);

  for (const row of parsed) {
    const lad24cd = NAME_TO_LAD24CD[row.la_name];
    if (!lad24cd) {
      unresolved.push({ la_name: row.la_name, financial_year: year });
      continue;
    }
    efsRows.push({
      lad24cd,
      financial_year: row.financial_year,
      amount_m: row.amount_m,
      status: row.status,
      hra_only: row.hra_only,
      source: `MHCLG Exceptional Financial Support for local authorities for ${year}`,
    });
  }
}

// ── Deduplicate EFS on (lad24cd, financial_year) — last writer wins ─────────
const efsMap = {};
for (const row of efsRows) {
  const key = `${row.lad24cd}|${row.financial_year}`;
  efsMap[key] = row;
}
const efsDeduped = Object.values(efsMap);

// ── Process S114 CSV ────────────────────────────────────────────────────────
const s114Raw = inputs[7].json.data;
const s114Parsed = parseS114Csv(s114Raw);
const s114Rows = s114Parsed.map(r => ({
  lad24cd:        r.lad24cd,
  notice_date:    r.notice_date,
  financial_year: r.financial_year,
  reason:         r.reason,
  date_confirmed: r.date_confirmed,
  source:         'IfG / Wikipedia / primary sources — compiled manually',
}));

return [{
  json: {
    efs_row_count:    efsDeduped.length,
    s114_row_count:   s114Rows.length,
    unresolved_count: unresolved.length,
    unresolved,
    efs_batch_json:   JSON.stringify(efsDeduped),
    s114_batch_json:  JSON.stringify(s114Rows),
  }
}];

