const raw = $input.first().json.data;

const lines = raw.trim().split('\n');
const headers = lines[0].split(',');

const suppress = new Set(['', '[z]', '[x]', '[c]']);

function safeInt(v) {
  if (!v || suppress.has(v.trim())) return null;
  const n = parseInt(v.replace(/,/g, '').trim());
  return isNaN(n) ? null : n;
}

function safeBool(v) {
  const s = v.trim().toUpperCase();
  if (s === 'TRUE') return true;
  if (s === 'FALSE') return false;
  return null;
}

// CSV parser — handles quoted fields (source column contains commas)
function parseLine(line) {
  const cols = [];
  let cur = '', inQ = false;
  for (const ch of line) {
    if (ch === '"') { inQ = !inQ; }
    else if (ch === ',' && !inQ) { cols.push(cur); cur = ''; }
    else { cur += ch; }
  }
  cols.push(cur);
  return cols;
}

const rows = [];
for (let i = 1; i < lines.length; i++) {
  if (!lines[i].trim()) continue;
  const cols = parseLine(lines[i]);
  const obj = {};
  headers.forEach((h, idx) => obj[h.trim()] = (cols[idx] || '').trim());

  rows.push({
    lad24cd:                  obj.lad24cd,
    reporting_year:           parseInt(obj.reporting_year),
    households_on_register:   safeInt(obj.households_on_register),
    jointly_managed_register: safeBool(obj.jointly_managed_register),
    reasonable_preference:    safeInt(obj.reasonable_preference),
    source:                   obj.source,
  });
}

return [{
  json: {
    row_count:  rows.length,
    batch_json: JSON.stringify(rows),
  }
}];

nodes.Process MARAC Data:
const maracRaw = $('Fetch MARAC CSV').first().json.data;
const mappingRaw = $('Fetch PFA Mapping CSV').first().json.data;

function parseCSV(text) {
  const lines = text.trim().split('\n');
  const headers = lines[0].split(',');
  return lines.slice(1).map(line => {
    const cols = [];
    let cur = '', inQ = false;
    for (const ch of line) {
      if (ch === '"') { inQ = !inQ; }
      else if (ch === ',' && !inQ) { cols.push(cur); cur = ''; }
      else { cur += ch; }
    }
    cols.push(cur);
    const obj = {};
    headers.forEach((h, i) => obj[h.trim()] = (cols[i] || '').trim());
    return obj;
  });
}

// Parse PFA mapping - build lookup: pfa_name_safelives -> [lad24cd, ...]
const mappingRows = parseCSV(mappingRaw);
const pfaToLads = {};
for (const r of mappingRows) {
  const key = r.pfa_name_safelives;
  if (!pfaToLads[key]) pfaToLads[key] = [];
  pfaToLads[key].push({
    lad24cd: r.lad24cd,
    la_name: r.la_name,
    population_weight: parseFloat(r.population_weight) || 1.0
  });
}

// Parse MARAC data
const maracRows = parseCSV(maracRaw);

const rows = maracRows.map(r => ({
  pfa_name_safelives: r.pfa_name_safelives,
  financial_year: r.financial_year,
  marac_count: r.marac_count === '' ? null : parseInt(r.marac_count) || null,
  cases_discussed: r.cases_discussed === '' ? null : parseFloat(r.cases_discussed) || null,
  recommended_cases: r.recommended_cases === '' ? null : parseFloat(r.recommended_cases) || null,
  cases_per_10k_adult_females: r.cases_per_10k_adult_females === '' ? null : parseFloat(r.cases_per_10k_adult_females) || null,
  repeat_cases: r.repeat_cases === '' ? null : parseFloat(r.repeat_cases) || null,
  repeat_cases_pct: r.repeat_cases_pct === '' ? null : parseFloat(r.repeat_cases_pct) || null,
  children_in_household: r.children_in_household === '' ? null : parseFloat(r.children_in_household) || null,
  housing_referrals: r.housing_referrals === '' ? null : parseFloat(r.housing_referrals) || null,
  source: r.source
}));

// PFA mapping rows for upsert
const mappingOut = mappingRows.map(r => ({
  lad24cd: r.lad24cd,
  la_name: r.la_name,
  pfa_name: r.pfa_name,
  pfa_name_safelives: r.pfa_name_safelives,
  population_weight: parseFloat(r.population_weight) || 1.0,
  source: r.source
}));

return [{
  json: {
    marac_rows: rows,
    marac_row_count: rows.length,
    mapping_rows: mappingOut,
    mapping_row_count: mappingOut.length,
    marac_batch_json: JSON.stringify(rows),
    mapping_batch_json: JSON.stringify(mappingOut)
  }
}];
